package edu.daa.dna; import edu.daa.dna.model.ApiModels.*;import edu.daa.dna.service.AnalysisService;import edu.daa.dna.validation.SequenceValidator;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class AnalysisServiceTest{@Test void normalizesAndBuildsTrace(){var r=new AnalysisService(new SequenceValidator()).analyze(new AnalyzeRequest(" a c g ","AC",true,true));assertEquals("ACG",r.sequenceA());assertEquals("AC",r.lcs());assertFalse(r.trace().isEmpty());}@Test void traceRecordsComputedValuesAndExplanations(){var r=new AnalysisService(new SequenceValidator()).analyze(new AnalyzeRequest("AC","AG",true,true));var mismatch=r.trace().stream().filter(e->e.algorithm().equals("LCS_TABULATION")&&e.row()==2&&e.column()==2).findFirst().orElseThrow();assertEquals(1,mismatch.value());assertTrue(mismatch.explanation().contains("max(upper"));assertEquals(r.trace().size(),r.trace().get(r.trace().size()-1).step());}@Test void selectedVariantsAreExecutedAndReported(){var r=new AnalysisService(new SequenceValidator()).analyze(new AnalyzeRequest("ACGT","ACT",false,false,"ROLLING_ROWS","MEMOIZATION"));assertEquals("ROLLING_ROWS",r.lcsAlgorithm());assertEquals("MEMOIZATION",r.editAlgorithm());assertEquals(3,r.lcsLength());assertEquals(1,r.editDistance());assertNull(r.lcsTable());}@Test void rejectsUnknownVariant(){assertThrows(IllegalArgumentException.class,()->new AnalysisService(new SequenceValidator()).analyze(new AnalyzeRequest("A","A",false,false,"FAST","TABULATION")));}@Test void rejectsInvalid(){assertThrows(IllegalArgumentException.class,()->new SequenceValidator().normalize("AC-G"));}}
